$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}
$files = @{}
$files['app/globals.css'] = ''
$files['components/app/sidebar.tsx'] = ''
$files['app/(app)/layout.tsx'] = ''
$files['components/app/app-shell.tsx'] = ''
$files['components/app/header.tsx'] = ''
$files['app/(app)/notifications/actions.ts'] = ''
$files['components/app/notification-bell.tsx'] = ''
$files['app/(app)/comments/actions.ts'] = ''
$files['components/app/comments-panel.tsx'] = ''
$files['components/app/record-tabs.tsx'] = ''
$files['components/app/activity-timeline-inner.tsx'] = ''
$files['app/(app)/accounts/[id]/page.tsx'] = ''
$files['app/(app)/contacts/[id]/page.tsx'] = ''
$files['app/(app)/deals/[id]/page.tsx'] = ''
$files['app/(app)/accounts/_components/accounts-table.tsx'] = ''
$files['app/(app)/contacts/_components/contacts-table.tsx'] = ''
$files['app/(app)/deals/_components/pipeline-kanban.tsx'] = ''
$files['app/(app)/deals/_components/kanban-column.tsx'] = ''
$files['app/(app)/admin/actions.ts'] = ''
$files['app/(app)/admin/page.tsx'] = ''
$files['app/(app)/admin/_components/user-admin-table.tsx'] = ''
$files['app/(app)/activities/_components/activities-list.tsx'] = ''
$files['app/(app)/accounts/page.tsx'] = ''
$files['app/(app)/contacts/page.tsx'] = ''
$files['app/(app)/deals/page.tsx'] = ''
$files['app/(app)/dashboard/page.tsx'] = ''

Write-Host '-> Day 5: collaboration + mobile' -ForegroundColor Cyan
Write-Host '   (comments, mentions, notifications, admin, mobile pass)' -ForegroundColor DarkGray
Write-Host ''
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}

Write-Host ''
Write-Host '====================================' -ForegroundColor Green
Write-Host '  Day 5 files written' -ForegroundColor Green
Write-Host '====================================' -ForegroundColor Green
Write-Host ''
Write-Host 'Test:' -ForegroundColor Cyan
Write-Host '  npm run dev' -ForegroundColor Gray
Write-Host '  http://localhost:3000/admin       (user mgmt)' -ForegroundColor Gray
Write-Host '  click any contact -> Comments tab (try @-mention)' -ForegroundColor Gray
Write-Host '  resize browser to ~400px wide     (mobile views)' -ForegroundColor Gray